      await page.click('#ink [data-inktool="erase"]'); await stroke(page, calc + ' > canvas.inkcv', 100, oy + 30, 100, oy + 110);
      const e1 = await ev(k => (FX.api('worksheets-ink').state().data.parts[k] || []).length, key);
      await page.click('#ink [data-inkundo]'); const e2 = await ev(k => (FX.api('worksheets-ink').state().data.parts[k] || []).length, key);
      check(e1 === 0 && e2 === 1, `the eraser removes a stroke it touches, and undo brings it back (${e1}, ${e2})`);
      await page.click('#ink [data-inkcolor="#1E56C8"]');
      check(await ev(() => { const I = FX.api('worksheets-ink').state(); return I.tool === 'pen' && I.color === '#1E56C8'; }), 'picking a colour returns to the pen in that colour');
      await ev(() => { document.getElementById('ink').scrollTop = 0; });
      await stroke(page, '#ink .wshead > canvas.inkcv', 80, 20, 180, 22);
      check(await ev(() => (FX.api('worksheets-ink').state().data.parts.head || []).length) === 1, 'the name line takes writing too');
      const res = await ev(k => { const c = document.querySelector(`#ink .wspart[data-ink="${k}"] > canvas.inkcv`), r = c.getBoundingClientRect(), ov = document.getElementById('ink'), I = FX.api('worksheets-ink').state();
        const e = (t, type, x, y, id) => c.dispatchEvent(new PointerEvent(type, {pointerType: t, clientX: r.left + x, clientY: r.top + y, pointerId: id, bubbles: true, isPrimary: true}));
        I.pencil = false; const before = (I.data.parts[k] || []).length;
        e('pen', 'pointerdown', 40, r.height - 80, 7); e('pen', 'pointermove', 90, r.height - 60, 7); e('pen', 'pointermove', 140, r.height - 50, 7); e('pen', 'pointerup', 140, r.height - 50, 7);
        const afterPen = (I.data.parts[k] || []).length, pencil = I.pencil;
        ov.scrollTop = 200; const top0 = ov.scrollTop;
        e('touch', 'pointerdown', 60, r.height - 100, 8); e('touch', 'pointermove', 60, r.height - 160, 8); e('touch', 'pointerup', 60, r.height - 160, 8);
        return [before, afterPen, pencil, (I.data.parts[k] || []).length, top0, ov.scrollTop]; }, key);
      check(res[1] === res[0] + 1 && res[2] && res[3] === res[1] && res[5] > res[4], `a pen writes and switches to Pencil only; then a finger scrolls the page and does not write ${JSON.stringify(res)}`);
      await page.click('#ink [data-inksol]');
      check(await ev(() => !document.querySelector('#ink .inksol').hidden && !!document.querySelector('#ink .inksol .wssp')), 'Show solutions opens the solutions under the worksheet');
      await page.click('#ink [data-inksol]');
      const sw = await ev(() => document.getElementById('ink').scrollWidth - document.getElementById('ink').clientWidth);
