        await ev(n => { window.__name = n; askProfile(true); }, first);
        const mine = await ev(([sid]) => [PROFILE, FX.api('worksheets-ink').inkCount(sid, 'main')], [sid]);
        check(other[1] === 0 && mine[1] === 3, `a second profile has no writing, and the first keeps its own (${JSON.stringify(other)}, ${JSON.stringify(mine)})`);
        await ev(() => show('settings'));
        const set = await ev(() => (document.getElementById('inkSize') || {}).textContent || '');
        check(/1 page with writing, 3 strokes/.test(set), `Settings says how much writing is kept (${set.slice(0, 80)})`);
