      await page.click('#v-quiz .inkscratch'); await page.waitForSelector('#ink .inkpaper .wsdoc');
      const info = await ev(() => [document.querySelector('#ink .wsq').textContent.length > 20, Math.round(document.querySelector('#ink .wswork').getBoundingClientRect().height),
        !!document.querySelector('#ink [data-inksol]'), FX.api('worksheets-ink').state().variant]);
