      check(await ev(() => (FX.api('worksheets-ink').state().data.parts.work || []).length) === 1, 'a stroke lands on the scratch paper');
      await page.click('#ink [data-inkdone]');
      const kept = await ev(id => FX.api('worksheets-ink').inkCount('q:' + id, 'scratch'), NUM);
      check(kept === 1 && !(await ev(() => !!document.getElementById('ink'))), `Done closes it and the writing is kept (${kept})`);
